Definition CLMAX10 : Z := 1844674407370955161.   (* [comment removed for export] *)
Definition A_CLMAX10 : Z := 0x14e08.

(* [comment removed for export] *)
Lemma land_fb1_40 : forall f, 0 <= f ->
  Z.land ((f / 256) mod 256) 40 = (if Z.testbit f 11 then 8 else 0) + (if Z.testbit f 13 then 32 else 0).
Proof. intros f Hf. change 40 with (2^3 + 2^5). rewrite land_mask2 by lia. rewrite !f_b1_testbit by lia. reflexivity. Qed.

Lemma land64_mod : forall x, Z.land x 18446744073709551615 = x mod 2^64.
Proof. intros x. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_ones by lia. reflexivity. Qed.

