(* [comment removed for export] *)
Definition dig_post (rax spx gp tp t0 t1 t2 s0 s1 a0 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m1 : mem) : machine_state -> Prop :=
  fun ms' => exists a1' a2' a3' a4' a5' pc',
    ms' = MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3' a4' a5' a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 pc') fc None m1 (seg_rom rsegs)
    /\ ((pc' = 0x3bb18 /\ exists v', a3' = wz v' /\ 0 <= v' < 2^64) \/ pc' = 0x3bb70).

Lemma cl_digits : forall (r : nat) (i v : Z) rax spx gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> mem_inv rsegs m1 -> vp + Z.of_nat (length vbs) < 2^64 ->
  vp <= vq -> 0 <= i -> vq + i + Z.of_nat r <= vp + Z.of_nat (length vbs) -> (1 <= r)%nat -> 0 <= v < 2^64 ->
  evt rsegs (dig_post rax spx gp tp t0 t1 t2 s0 s1 a0 a6 a7 s2 s3 (wz CLMAX10) (wz (-10)) (wz 10) s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1)
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0 (wz (Z.of_nat r)) (wz (vq + i)) (wz v) a4 a5 a6 a7 s2 s3 (wz CLMAX10) (wz (-10)) (wz 10) s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3bae8) fc None m1 (seg_rom rsegs)).
