(* [comment removed for export] *)
(* [comment removed for export] *)
Section CL.
  Hypothesis OPTI : optit_incr_stmt.
  Hypothesis VALID : validate_list_stmt.

Local Ltac dof_finish c' E' g' :=
  apply evt_done; unfold dof_post;
  do 16 eexists; exists c', E', g';
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.

(* [comment removed for export] *)
Definition cl_ctx (m m1 : mem) (sp : word) (sv : list word) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte)
    (vp : Z) (vbs : list byte) (j1 : list byte) (optc : list cell) (jt : list byte) (e1 e2 e3 : word) (g : bool) : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 128 j1]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -160) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -144) [C8 (wz E)]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -136) optc
  /\ rw_cells rsegs m1 (bv_unsigned sp + -96) [CB 24 jt]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -72) (map C8 sv)
  /\ rw_cells rsegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells rsegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at rsegs m1 vp vbs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -288)
  /\ munch (dof_W lo sp P E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

Definition CL_AT (B : Z) : Prop :=
  forall (itc vq vl err : Z) rax ra sp gp tp t0 t1 t2 (a0w : word) a1 a2 a3 a4 a5 a6 a7 (s2w s3w : word)
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j1 pad7o jt : list byte) (e1 e2 e3 : word) (g : bool),
  cl_ctx m m1 sp (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 vp vbs j1
         (OptItCells (bv_unsigned sp + -160) itc vq vl err pad7o) jt e1 e2 e3 g ->
  dof_pure sp P E lo c (pc_state c) vp vbs ->
  vp <= vq -> 0 <= vl -> vq + vl = itc -> itc <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) - itc < B ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0w a1 a2 a3 a4 a5 a6 a7
              s2w s3w (wz CLMAX10) (wz (-10)) (wz 10) (Z_to_bv 64 (bv_unsigned sp + -160)) s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3bad8) fc None m1 (seg_rom rsegs)).

Local Ltac cl_open CTX PURE sp :=
  pose proof PURE as PURE0; pose proof CTX as CTX0;
  destruct CTX as (FR1 & LSV & CLO & OPT & TMPB & FRhi & PC & EC & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & FLD & LO & IMG & QLO & QHI & PLO & PHI & ELO & EHI & DPE);
  pose proof PCOK as PCOK0; destruct PCOK as (Bh & Bl & Ln & Ln0 & Sk & Hl & Stt & Ff);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold dof_W, G_HTTP_CAT in *; unfold dof_sv in FRhi; cbn [map] in FRhi;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold CLMAX10, wz in *.

(* [comment removed for export] *)
Local Ltac cl_blobB FR1 LSV CLO OPT :=
  let jo := fresh "jo" in let OPTb := fresh "OPTb" in
  destruct (rw_cells_forget _ _ _ _ OPT) as [jo OPTb]; cbn [cells_size csize Nat.add OptItCells] in OPTb; clear OPT;
  blob2 FR1 LSV; blob2 FR1 CLO; blob2 FR1 OPTb.

(* [comment removed for export] *)
Lemma cl_exit_B : forall pc e loc, dof_exitB_stmt pc e loc ->
  forall (optc : list cell) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j1 jt : list byte) (e1 e2 e3 : word) (g : bool),
  cl_ctx m m1 sp (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 vp vbs j1 optc jt e1 e2 e3 g -> cells_size optc = 40%nat ->
  dof_pure sp P E lo c (pc_state c) vp vbs ->
  In e [HE_BAD_VALUE; HE_BAD_CONTENT_LENGTH; HE_BAD_TRANSFER_ENCODING; HE_MULTIPLE_CONTENT_LENGTH] ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).
Proof.
  intros pc e loc EX optc rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo c pad7 pad2 vp vbs j1 jt e1 e2 e3 g CTX SO PURE HE.
  pose proof PURE as PURE0.
  destruct CTX as (FR1 & LSV & CLO & OPT & TMPB & FRhi & PC & EC & WIN & HC & XS & ST & MU & WM & MI).
  destruct PURE as (PCOK & FLD & LO & IMG & QLO & QHI & PLO & PHI & ELO & EHI & DPE).
