Lemma cl_all : forall n, CL_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros itc vq vl err. intros until g. intros CTX PURE N1 N2 N3 N4 NM. exfalso. cbn [Z.of_nat] in NM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply cl_step. exact IH.
Qed.


(* [comment removed for export] *)
Local Ltac cl_exit_c08 FR1 LSV CLO OPT TMPB PURE0 PCOK0 :=
  let jl := fresh "jl" in let LSVb := fresh "LSVb" in let jc := fresh "jc" in let CLOb := fresh "CLOb" in
  let jo := fresh "jo" in let OPTb := fresh "OPTb" in let X16 := fresh "X16" in let EX := fresh "EX" in
  destruct (rw_cells_forget _ _ _ _ LSV) as [jl LSVb]; cbn [cells_size csize Nat.add] in LSVb; clear LSV;
  destruct (rw_cells_forget _ _ _ _ CLO) as [jc CLOb]; cbn [cells_size csize Nat.add] in CLOb; clear CLO;
  destruct (rw_cells_forget _ _ _ _ OPT) as [jo OPTb]; cbn [cells_size csize Nat.add OptItCells] in OPTb; clear OPT;
  blob2 FR1 LSVb; blob2 FR1 CLOb;
  cb_split OPTb 24%nat X16; blob2 X16 TMPB;
  pose proof dof_exit_c08 as EX; unfold dof_exitA_stmt in EX; unfold wz in EX;
  eapply EX; [ | exact FR1 | exact OPTb | exact X16 | exact PURE0 | apply dof_core_refl; exact PCOK0 | cbn; qtauto ];
  unfold dof_ctx, dof_sv, dof_W, G_HTTP_CAT, ParserCoreCells; cbn [map pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
  repeat match goal with |- _ /\ _ => split end; try fast_eassumption.

(* [comment removed for export] *)
Lemma cl_p2 : forall rax ra sp gp tp t0 t1 t2 a0 a1 a4 a5 a6 a7 s2x s3x s4x s5x s6x s7x
         s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j1 jl jo jt : list byte) (e1 e2 e3 : word) (g : bool),
  rw_cells rsegs m1 (bv_unsigned sp + -288) [CB 128 j1] ->
  rw_cells rsegs m1 (bv_unsigned sp + -160) [CB 16 jl] ->
  rw_cells rsegs m1 (bv_unsigned sp + -144) [C8 (wz E)] ->
  rw_cells rsegs m1 (bv_unsigned sp + -136) [CB 40 jo] ->
  rw_cells rsegs m1 (bv_unsigned sp + -96) [CB 24 jt] ->
  dof_ctx m m1 sp (dof_sv s7v s6v s5v s4v s3v s2v s1v s0v ra) P E lo c pad7 pad2 vp vbs e1 e2 e3 g ->
  dof_pure sp P E lo c (pc_state c) vp vbs ->
  evt rsegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 (wz vp) (wz (Z.of_nat (length vbs))) a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6)
