    (F : bvmap 5 word) fc (m1 : mem) (vp : Z) (vbs : list byte),
  bytes_at rsegs m1 vp vbs -> mem_inv rsegs m1 -> vp + Z.of_nat (length vbs) < 2^64 -> (1 <= length vbs)%nat ->
  evt rsegs (fun ms' => exists a0' a1' a4' s2',
      ms' = MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0' a1' a2 a3 a4' a5 a6 a7 s2' s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 0x3b9e4) fc None m1 (seg_rom rsegs))
    (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz (Z.of_nat (length vbs))) (wz vp) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3b8e8) fc None m1 (seg_rom rsegs)).
Proof.
  intros rax spx gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vbs WIN MI V3 L1.
  pose proof (cl_commas (length vbs) 0 rax spx gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1 vp vbs
